-- DROP TABLES IF THEY EXIST
DROP TABLE IF EXISTS entregas_estrategicas;
DROP TABLE IF EXISTS municipios;

-- CREATE TABLE municipios
CREATE TABLE municipios (
    codigo_ibge TEXT PRIMARY KEY,
    municipio TEXT,
    populacao INTEGER,
    comarca TEXT,
    polo_regional TEXT,
    municipio_slug TEXT,
    comarca_slug TEXT,
    polo_regional_slug TEXT,
    opm_possui TEXT,
    opm_status_politicas_publicas TEXT,
    opm_orgaotipo TEXT,
    opm_possui_estrutura_ativa TEXT,
    creas_possui TEXT,
    creas_status TEXT,
    creas_ausente TEXT,
    prioridade_implantacao_creas TEXT,
    prioridade_fomento_opm TEXT,
    consumado INTEGER,
    tentado INTEGER,
    consumado_2023 INTEGER,
    consumado_2024 INTEGER,
    consumado_2025 INTEGER,
    consumado_2026 INTEGER,
    tentado_2023 INTEGER,
    tentado_2024 INTEGER,
    tentado_2025 INTEGER,
    tentado_2026 INTEGER,
    feminicidios_total_2023_2026 INTEGER,
    tentativas_total_2023_2026 INTEGER,
    ocorrencias_total_violencia_genero_monitoradas INTEGER,
    indicador_tem_feminicidio_consumado TEXT,
    indicador_tem_tentativa_feminicidio TEXT,
    risco_feminicidio_nivel TEXT,
    risco_feminicidio_score INTEGER,
    painel_alerta_rede TEXT,
    necessita_atuacao_prioritaria TEXT,
    status_monitoramento TEXT,
    fonte_base_opm TEXT,
    fonte_base_creas TEXT,
    fonte_base_risco TEXT,
    observacoes_sistema TEXT,
    ultima_atualizacao_referencia TEXT,
    id TEXT
);

-- CREATE TABLE entregas_estrategicas
CREATE TABLE entregas_estrategicas (
    id SERIAL PRIMARY KEY,
    titulo TEXT NOT NULL,
    responsavel TEXT,
    prazo TEXT,
    status TEXT,
    progresso INTEGER,
    descricao TEXT
);

